## Why This Is Asked
This question evaluates advanced JavaScript patterns including per-key caching, Promise deduplication, TTL-based eviction, and reactive update patterns commonly needed in frontend applications.

## Key Concepts
- **Closures and per-key maps**: Isolated state management for each cached key
- **Promise deduplication**: Avoiding redundant network requests for concurrent loads of the same key
- **TTL-based eviction**: Time-to-live expiration for cache entries
- **Change notifications**: Listener pattern for broadcasting data updates
- **Error handling**: Graceful handling of fetch failures and cache misses

## Code Example
```javascript
function createDataLoader(fetchFn, ttlMs) {
  const cache = new Map();

  function getEntry(key) {
    if (!cache.has(key)) {
      cache.set(key, { promise: null, data: null, expiry: 0, listeners: [] });
    }
    return cache.get(key);
  }

  const notify = (key, data, error) => {
    const entry = cache.get(key);
    if (entry?.listeners.length) {
      entry.listeners.forEach(cb => cb(data, error));
    }
  };

  return {
    load(key) {
      const entry = getEntry(key);
      const now = Date.now();

      if (entry.data && entry.expiry > now) {
        return Promise.resolve(entry.data);
      }

      if (entry.promise) {
        return entry.promise;
      }

      entry.promise = fetchFn(key)
        .then(data => {
          entry.data = data;
          entry.expiry = now + ttlMs;
          entry.promise = null;
          notify(key, data, null);
          return data;
        })
        .catch(err => {
          entry.promise = null;
          notify(key, null, err);
          throw err;
        });

      return entry.promise;
    },

    invalidate(key) {
      const entry = cache.get(key);
      if (entry) {
        entry.data = null;
        entry.expiry = 0;
        entry.promise = null;
      }
    },

    onChange(key, cb) {
      const entry = getEntry(key);
      entry.listeners.push(cb);
      return () => {
        entry.listeners = entry.listeners.filter(l => l !== cb);
      };
    }
  };
}
```

## Usage Example
```javascript
const loader = createDataLoader(fetchUser, 5000);

// Two different keys
loader.onChange('user:1', (data) => console.log('User 1 updated:', data));
loader.onChange('user:2', (data) => console.log('User 2 updated:', data));

// Concurrent loads for same key are deduplicated
loader.load('user:1').then(console.log);
loader.load('user:1').then(console.log); // Reuses in-flight request

// Invalidate and reload
loader.invalidate('user:1');
loader.load('user:1');
```

## Eviction Strategies
- **TTL-based**: Automatic expiration after ttlMs (implemented above)
- **LRU**: Evict least recently used entries when cache size exceeds limit
- **Manual**: Explicit invalidate() calls

## Error Handling
- Failed fetches propagate errors to all waiters via rejected Promise
- Listeners receive error state for reactive UI updates
- In-flight promises are cleared on error to allow retries

## Why This Is Asked
Tests the ability to combine fetch, Service Workers, and WebSockets with a practical offline-first UI. Emphasizes conflict resolution via last-writer-wins and a lightweight diff/apply strategy.

## Key Concepts
- Offline-first fetch with Service Worker caching
- WebSocket reconnection strategy with exponential backoff
- Minimal DOM diff/patch engine for efficient row updates
- Offline edit queue with replay on reconnect and per-item last-writer-wins conflict resolution

## Code Example
```javascript
// Fetch wrapper sketch
function createFetchWrapper(baseUrl) {
  return async function fetchWrapper(endpoint, options = {}) {
    const cache = await caches.open('inventory-v1');
    const cached = await cache.match(baseUrl + endpoint);

    if (cached && !options.forceRefresh) {
      return cached;
    }

    const response = await fetch(baseUrl + endpoint, options);
    if (response.ok) {
      cache.put(baseUrl + endpoint, response.clone());
    }
    return response;
  };
}

// WebSocket wrapper sketch
function createWsWrapper(url, handlers) {
  let ws = null;
  let retryDelay = 1000;
  const editQueue = [];

  function connect() {
    ws = new WebSocket(url);

    ws.onopen = () => {
      retryDelay = 1000;
      replayQueue();
      handlers.onOpen?.();
    };

    ws.onmessage = (e) => handlers.onMessage(JSON.parse(e.data));

    ws.onclose = () => {
      setTimeout(connect, retryDelay);
      retryDelay = Math.min(retryDelay * 2, 30000);
    };
  }

  function replayQueue() {
    while (editQueue.length) {
      ws.send(JSON.stringify(editQueue.shift()));
    }
  }

  connect();

  return {
    send: (data) => {
      if (ws.readyState === WebSocket.OPEN) {
        ws.send(JSON.stringify(data));
      } else {
        editQueue.push(data);
      }
    }
  };
}

// Diff applier sketch
function applyDiff(currentItems, updates) {
  const itemMap = new Map(currentItems.map(item => [item.id, item]));

  for (const update of updates) {
    const existing = itemMap.get(update.id);
    if (!existing || update.ts > existing.ts) {
      itemMap.set(update.id, update);
    }
  }

  return Array.from(itemMap.values()).sort((a, b) => b.ts - a.ts);
}
```

